CREATE TABLE IF NOT EXISTS pipeline_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(120) NOT NULL, slug varchar(140) NOT NULL UNIQUE, description text, category varchar(30) NOT NULL DEFAULT 'custom' CHECK (category IN ('sales','support','onboarding','recruitment','custom')), stages jsonb NOT NULL DEFAULT '[]'::jsonb, is_builtin boolean NOT NULL DEFAULT false, preview_image_url text, date_created timestamptz NOT NULL DEFAULT now(), date_updated timestamptz NOT NULL DEFAULT now());
